  ('lintong-nihuta', 310, 'Indonesia', 'インドネシア', false, 'Specialty', '[]'::jsonb, 'Lintong Nihuta', '', 'Semi Washed (Smatra Process)', 'Anton Johan Ali', 'Smatra, Lintong, Nihuta', '1200-1400', 'Typica', '[]'::jsonb, '', 'Medium Dark roast', 'tropical, spicy, manderin like', '', '5kg', false, false, 5670, null),
  ('seasonal-blend', 320, 'Original Blend', 'オリジナルブレンド', true, '', '[]'::jsonb, 'Seasonal Blend “夢見草”', '', 'Natural / Washed / Washed', '', '', '', '74110,74112, Heirloom, Geisha', '[{"origin":"Ethiopia","process":"Natural"},{"origin":"Ethiopia","process":"Washed"},{"origin":"Guatemala","process":"Washed"}]'::jsonb, '', 'Medium-Light Roast', 'Earl Grey, Floral, Bergamot, Bright Acidity, Honey, Green Tea', '昔、儚く夢のように散る姿から桜のことを夢見草と呼んだというところから、春に向けて、飲み口は華やかですがサっと爽やかに消え、後味はお茶のように飲みやすいブレンドを目指して作りました。', '', false, true, 8237, null),
  ('new-signature-ring-of-the-water', 330, 'Original Blend', 'オリジナルブレンド', true, '', '[]'::jsonb, 'New Signature “Ring of the Water”', '', 'Red honey / Washed / Washed / Wine Yeast Lychee', '', '', '', 'Heirloom, Heirloom, Caturra,, Pache, Castillo', '[{"origin":"Ethiopia Guji Uraga Red Honey","process":"Red honey"},{"origin":"Ethiopia Yirgacheffe Worka Sakaro W","process":"Washed"},{"origin":"Guatemala Todos Santos","process":"Washed"},{"origin":"Colombia Finca Jardines del Eden","process":"Wine Yeast Lychee"}]'::jsonb, '', 'Medium-Light Roast', '', '新しいシグネチャーとなるように作成したブレンドHappiness Bloomよりもさらにフルーティさが前回の中浅煎りを目指して作っています。アバアスのロゴにある “波紋”のような味わいを目指し、白ワインのようなフレーバーやテイストが口に含んだ瞬間からしっかりとありながらも、アフターにかけて徐々に穏やかになりながら、でも長く広がっていくようなコーヒーです。', '', false, true, 8237, null),
  ('happiness-bloom-dark-edition-special', 340, 'Original Blend', 'オリジナルブレンド', true, '', '[]'::jsonb, 'Happiness Bloom Dark Edition Special', '', 'Carbonic Maceration / Natural / Washed / Lactic Natural / Wine Yeast Strawberry', '', '', '', 'Heirloom, Yellow Bourbon, Castillo, Typica', '[{"origin":"Ethiopia Bench Maji Gesha Zone Karmachi","process":"Carbonic Maceration"},{"origin":"Ethiopia Yirgacheffe Worka Sakaro","process":"Natural"},{"origin":"Guatemala Huehuetenango Todos Santos Regional","process":"Washed"},{"origin":"El Salvador Santa Rita","process":"Lactic Natural"},{"origin":"Colombia Finca Jardines del Eden","process":"Wine Yeast Strawberry"}]'::jsonb, '', 'Medium-Dark Roast', '', '深煎りとは思えないようなフルーティーさを目指して作ったブレンド。冷めるにつれストロベリー感が増していく不思議な深煎りです。', '60kg', false, true, 7070, null),
  ('sigunature-blend-happiness-bloom-ver-25-26-fall-wintter', 350, 'Original Blend', 'オリジナルブレンド', true, '', '["yearRound"]'::jsonb, 'Sigunature Blend “Happiness Bloom”', 'ver. 25-26 Fall/Wintter', 'Red Honey / Washed / Natural / Natural', '', '', '', 'Heirloom, Heirloom, Geisha, Caturra, Pache', '[{"origin":"Ethiopia Guji Uraga Red Honey","process":"Red Honey"},{"origin":"Ethiopia Yirgacheffe Worka Sakaro W","process":"Washed"},{"origin":"Costa Rica Canderilla “Geisha”","process":"Natural"},{"origin":"Guatemala Todos Santos","process":"Natural"}]'::jsonb, '', 'Medium-Light roast', 'Hint of Red Grape, Berry, Orange, Yellow Peach, Honey, Round, Sweet', 'ABOUT US COFFEEのテーマである「Wish your happiness bloom, with a cup of bliss…」（至福の一杯とともにあなたに幸せが咲き誇りますように」から逆算して作るブレンド。このテーマに沿ったブレンド配合にその都度変更します。', '', false, true, 6370, null),
  ('sigunature-blend-daily-little-happiness', 360, 'Original Blend', 'オリジナルブレンド', true, '', '["yearRound"]'::jsonb, 'Sigunature Blend “Daily Little Happiness”', '', 'Washed / Natural / Washed / Fully Washed', '', '', '', '', '[{"origin":"Guatemala","process":"Washed"},{"origin":"Guatemala","process":"Natural"},{"origin":"Ethiopia","process":"Washed"},{"origin":"Colombia","process":"Fully Washed"}]'::jsonb, '', 'Midium roast', 'Prum, Pear, Stone Fruit, Milk Chocolate, Roasted Nuts, Broown Sugar', '毎日飲んでも飽きないようなブレンドのコンセプトで、ラテの場合はミルクの甘味が引き立つようになっています。ドリップでも酸味が尖りすぎず、苦すぎず、毎朝目覚めの一杯に優しく飲めるコーヒーのようなイメージです。', '', false, true, 4737, null),
  ('best-wishes-blend', 370, 'Original Blend', 'オリジナルブレンド', true, '', '["yearRound"]'::jsonb, 'Best Wishes Blend', '', 'Pulped Natural / Natural / Washed', '', '', '', '', '[{"origin":"Brazil","process":"Pulped Natural"},{"origin":"Ethiopia","process":"Natural"},{"origin":"Ethiopia","process":"Washed"}]'::jsonb, '', 'Midium roast', 'Stone fruit, Citrus , Caramel, Brown sugar, Round, Sweet After', '', '', false, true, 5437, null),
  ('espresso-blend-traditional', 380, 'Original Blend', 'オリジナルブレンド', true, '', '["yearRound"]'::jsonb, 'Espresso Blend “Traditional”', '', 'Washed / Pulped Natural / Natural / Washed / Washed', '', '', '', '', '[{"origin":"Colombia","process":"Washed"},{"origin":"Brazil","process":"Pulped Natural"},{"origin":"Ethiopia","process":"Natural"},{"origin":"Ethiopia","process":"Washed"},{"origin":"Guatemala","process":"Washed"}]'::jsonb, '', 'Midium Dark roast', 'Milk Chocolate, Caramel, Dried Date, Mix Nuts, Raisin, Tropical', '毎日飲んでも飽きないようなブレンドのコンセプトで、ラテの場合はミルクの甘味が引き立つようになっています。ドリップでも酸味が尖りすぎず、苦すぎず、毎朝目覚めの一杯に優しく飲めるコーヒーのようなイメージです。', '', false, true, 4737, null),
  ('espresso-blend-basic', 390, 'Original Blend', 'オリジナルブレンド', true, '', '["yearRound"]'::jsonb, 'Espresso Blend “Basic”', '', 'Pulped Natural / Natural / Fully Washed', '', '', '', '', '[{"origin":"Brazil","process":"Pulped Natural"},{"origin":"Ethiopia","process":"Natural"},{"origin":"Colombia","process":"Fully Washed"}]'::jsonb, '', 'Midium-Dark roast', '', '焙煎度合が深すぎないのでカフェラテにした時にも苦味が出過ぎずにキャラメルのような甘味があり、かつ浅すぎもしないので酸味も少なく、ラテアートも描きやすいバランスの取れたポイントで焙煎しています。もちろんドリップでも美味しく飲めます。', '', false, false, 5437, null),
  ('classic-blend', 400, 'Original Blend', 'オリジナルブレンド', true, '', '["yearRound"]'::jsonb, 'Classic Blend', '', 'Pulped Natural / Washed / Fully Washed', '', '', '', '', '[{"origin":"Brazil","process":"Pulped Natural"},{"origin":"Ethiopia","process":"Washed"},{"origin":"Colombia","process":"Fully Washed"}]'::jsonb, '', 'Dark roast', '', 'ブラジルが主体のクラシカルなブレンドをイメージ。年配の方に受けそうなしっかりとコクのあるコーヒーです。', '', false, false, 5437, null),
  ('de-cafe-blend-medium-roast', 410, 'Original Blend', 'オリジナルブレンド', true, '', '["yearRound"]'::jsonb, 'De Cafe Blend Medium Roast', '', 'Washed / Fully Washed / Washed', '', '', '', '', '[{"origin":"Ethiopia","process":"Washed"},{"origin":"Colombia","process":"Fully Washed"},{"origin":"Guatemala","process":"Washed"}]'::jsonb, '', 'Medium roast', 'Stone Fruit, Citrus, Caramel, Milk Chocolate,', '焙煎度合がやや浅めでも美味しく、安定的に提供できるディカフェとなるようにブレンドしています。', '', false, false, 5903, null),
  ('de-cafe-blend-dark-roast', 420, 'Original Blend', 'オリジナルブレンド', true, '', '["yearRound"]'::jsonb, 'De Cafe Blend Dark Roast', '', 'Washed / Fully Washed / Washed', '', '', '', '', '[{"origin":"Ethiopia","process":"Washed"},{"origin":"Colombia","process":"Fully Washed"},{"origin":"Guatemala","process":"Washed"}]'::jsonb, '', 'Dark roast', '', 'ミディアムローストで作ったディカフェブレンドを深煎り需要のためにダークローストでも焙煎いたします', '', false, false, 5903, null)
